`timescale 1ns/1ps
// =============================================================
// vhfastmulb16_mul_bf16_bf16_fp32_lat4_rand_tb.v
// Random/directed regression for vhfastmulb16_mul_bf16_bf16_fp32_lat4.
//
// Vectors are generated by scripts/gen_f32_vectors.py into
// build/vhfastmulb16_mul_bf16_bf16_fp32_lat4_rand.hex (one 64-bit word per line):
//   [63:48] = BF16 A
//   [47:32] = BF16 B
//   [31:0]  = expected F32 exact product (RTZ for F32 subnormal)
//
// The stream test uses LAT = 4 and checks pair k-LAT on cycle k.
// Also checks en=0 HOLD and reset priority.
// =============================================================

module vhfastmulb16_mul_bf16_bf16_fp32_lat4_rand_tb;

    localparam integer N         = 2048;  // must match generator --count
    localparam integer LAT       = 4;
    localparam integer MAX_PRINT = 20;
    localparam integer VEC_FILE_LINES = N;

    reg         clk;
    reg         reset;
    reg         en;
    reg  [15:0] ina;
    reg  [15:0] inb;
    wire [31:0] outc;

    vhfastmulb16_mul_bf16_bf16_fp32_lat4 uut (
        .clk   (clk),
        .reset (reset),
        .en    (en),
        .ina   (ina),
        .inb   (inb),
        .outc  (outc)
    );

    reg [63:0] vec [0:N-1];

    integer k;
    integer checked;
    integer errors;
    reg [31:0] hold_val;

    task check(input integer idx);
        reg [15:0] va;
        reg [15:0] vb;
        reg [31:0] ve;
        begin
            va = vec[idx][63:48];
            vb = vec[idx][47:32];
            ve = vec[idx][31:0];
            checked = checked + 1;
            if (outc !== ve) begin
                errors = errors + 1;
                if (errors <= MAX_PRINT) begin
                    $display("[ERROR] t=%0t | pair %0d | a=%h b=%h",
                             $time, idx, va, vb);
                    $display("        exp: outc=%h | got: outc=%h", ve, outc);
                end
            end
        end
    endtask

    // ---------------- Clock generation 100 MHz ----------------
    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // ---------------- RESET: 5 clk ----------------
    initial begin
        reset = 1'b1;
        en    = 1'b0;
        ina   = 16'h0000;
        inb   = 16'h0000;
        repeat (5) @(negedge clk);
        reset = 1'b0;
    end

    // ---------------- Main scenario ----------------
    initial begin
        $dumpfile("build/vhfastmulb16_mul_bf16_bf16_fp32_lat4_rand.vcd");
        $dumpvars(0, vhfastmulb16_mul_bf16_bf16_fp32_lat4_rand_tb);

        $readmemh("build/vhfastmulb16_mul_bf16_bf16_fp32_lat4_rand.hex", vec, 0, VEC_FILE_LINES - 1);

        checked = 0;
        errors  = 0;

        // Wait for reset release + 10 clocks.
        @(negedge reset);
        repeat (10) @(negedge clk);

        if (outc !== 32'h0000_0000) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | after reset: exp outc=00000000, got outc=%h",
                     $time, outc);
        end

        // Stream N pairs, one per clock. Result of pair k appears on k+4.
        for (k = 0; k < N + LAT; k = k + 1) begin
            @(posedge clk); #1;

            if (k < N) begin
                ina = vec[k][63:48];
                inb = vec[k][47:32];
                en  = 1'b1;
            end else begin
                en = 1'b0;
            end

            if (k >= LAT)
                check(k - LAT);
        end

        // ---- en=0 HOLD ----
        en  = 1'b0;
        ina = 16'h7FC0;
        inb = 16'h3F80;
        @(posedge clk); #1;
        hold_val = outc;
        repeat (6) @(posedge clk); #1;
        if (outc !== hold_val) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | en=0 hold: exp outc=%h, got outc=%h",
                     $time, hold_val, outc);
        end

        // ---- reset priority over en ----
        en    = 1'b1;
        reset = 1'b1;
        @(posedge clk); #1;
        if (outc !== 32'h0000_0000) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | reset priority: exp outc=00000000, got outc=%h",
                     $time, outc);
        end
        reset = 1'b0;
        en    = 1'b0;

        repeat (10) @(posedge clk);

        $display("---------------------------------------------");
        $display("Checked vectors: %0d", checked);
        $display("Errors:          %0d", errors);
        if (errors == 0)
            $display("TEST PASSED");
        else
            $display("TEST FAILED");
        $display("---------------------------------------------");
        $finish;
    end

    // ---------------- Watchdog ----------------
    initial begin
        #5000000;
        $display("[ERROR] Testbench timeout!");
        $finish;
    end

endmodule
